):
    # 旧值取接管前，旧会话无地址时旧地址为 ""；新会话状态恒为在线。
    payload = {
        "旧会话": old,
        "旧地址": old_address,
        "旧期限": old_deadline,
        "旧租期": old_lease,
        "新会话": sid,
        "状态": _STATE_ONLINE,
        "时刻": now_ms,
        "期限": deadline,
        "池": pool_id,
        "地址": address,
        "租期": lease,
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"

