    required_leases = {}
    for row in sessions:
        if row["池"] == "":
            continue
        pool = self._pools.get(row["池"])
        if pool is None:
            raise ResourceError(
                f"checkpoint cannot carry lease of sid {row['会话']!r}: "
                f"no pool {row['池']!r}"
            )
        ip_int = _check_ip("会话.地址", row["地址"])
        try:
            network = ipaddress.IPv4Network(pool.cidr, strict=True)
        except ValueError as exc:
            raise ResourceError(str(exc)) from exc
        if ip_int not in set(network.hosts()) or ip_int in pool.reserved:
            raise ResourceError(
                f"checkpoint cannot carry lease of sid {row['会话']!r}: "
                f"address {row['地址']} not usable in pool {row['池']!r}"
            )
        if ip_int in pool.static_ips and pool.static.get(row["用户"]) != ip_int:
            raise ResourceError(
                f"checkpoint cannot carry lease of sid {row['会话']!r}: "
                f"address {row['地址']} is static for another user"
            )
        pool_leases = required_leases.setdefault(row["池"], {})
        if ip_int in pool_leases:
            raise ResourceError(
                f"address {row['地址']} in pool {row['池']!r} rented by "
                f"{pool_leases[ip_int]!r} and {row['会话']!r}"
            )
        pool_leases[ip_int] = row["会话"]

    # 全部校验通过：原子提交会话、租约、队列与账本。
    for row in sessions:
        if row["池"] == "":
            pool_id = None
            ip_int = None
        else:
            pool_id = row["池"]
            ip_int = _check_ip("会话.地址", row["池"] and row["地址"])
        self._sessions[row["会话"]] = {
            "user": row["用户"],
            "state": row["状态"],
            "deadline": row["期限"],
            "ip": ip_int,
            "lease": row["租期"],
            "pool": pool_id,
            "meter": None,
        }
    for pool_id, pool_leases in required_leases.items():
        pool = self._pools[pool_id]
        pool.leases.update(pool_leases)
        pool.free = [ip_int for ip_int in pool.free if ip_int not in pool_leases]
        heapq.heapify(pool.free)
    self._capacity_queue = {
        row["会话"]: [
            row["用户"],
            row["申请时刻"],
            row["等待"],
            row["截止"],
            row["入队序"],
        ]
        for row in queued
    }
    self._queue_order = [row["会话"] for row in queued]
    self._queue_seq = queued[-1]["入队序"] if queued else 0
    self._capacity_events = list(events)
    self._capacity_tail = events[-1][6] if events else "0" * 64
    return self.capacity_stats(now_ms)

